import { test, expect } from '@playwright/test';

test.describe('Image Alt Text Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/images');
  });

  test('should display descriptive alt text for all images', async ({ page }) => {
    // Verify the first image has descriptive alt text
    const firstImage = page.getByRole('img', { name: /first image/i });
    await expect(firstImage).toBeVisible();
    await expect(firstImage).toHaveAttribute('alt', /first image description/i);

    // Verify the second image has descriptive alt text
    const secondImage = page.getByRole('img', { name: /second image/i });
    await expect(secondImage).toBeVisible();
    await expect(secondImage).toHaveAttribute('alt', /second image description/i);

    // Verify the third image has descriptive alt text
    const thirdImage = page.getByRole('img', { name: /third image/i });
    await expect(thirdImage).toBeVisible();
    await expect(thirdImage).toHaveAttribute('alt', /third image description/i);

    // Verify the fourth image has descriptive alt text
    const fourthImage = page.getByRole('img', { name: /fourth image/i });
    await expect(fourthImage).toBeVisible();
    await expect(fourthImage).toHaveAttribute('alt', /fourth image description/i);

    // Verify the fifth image has descriptive alt text
    const fifthImage = page.getByRole('img', { name: /fifth image/i });
    await expect(fifthImage).toBeVisible();
    await expect(fifthImage).toHaveAttribute('alt', /fifth image description/i);
  });

  test('should handle images with empty alt text gracefully', async ({ page }) => {
    // Verify the first image has descriptive alt text
    const firstImage = page.getByRole('img', { name: /first image/i });
    await expect(firstImage).toBeVisible();
    await expect(firstImage).toHaveAttribute('alt', /first image description/i);

    // Verify the second image has empty alt text
    const secondImage = page.getByRole('img', { name: /second image/i });
    await expect(secondImage).toBeVisible();
    await expect(secondImage).toHaveAttribute('alt', '');

    // Verify the third image has descriptive alt text
    const thirdImage = page.getByRole('img', { name: /third image/i });
    await expect(thirdImage).toBeVisible();
    await expect(thirdImage).toHaveAttribute('alt', /third image description/i);

    // Verify the fourth image has empty alt text
    const fourthImage = page.getByRole('img', { name: /fourth image/i });
    await expect(fourthImage).toBeVisible();
    await expect(fourthImage).toHaveAttribute('alt', '');

    // Verify the fifth image has descriptive alt text
    const fifthImage = page.getByRole('img', { name: /fifth image/i });
    await expect(fifthImage).toBeVisible();
    await expect(fifthImage).toHaveAttribute('alt', /fifth image description/i);
  });
});
